INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-291796', '20 Minute White Bean Chili', 30, ARRAY['turkey', 'chicken'], '["in 3 quart saucepan , over medium heat , saute onions and garlic in oil until tender", "add turkey", "cook until done , stirring occasionally to break up meat", "drain", "stir in tomatoes , chicken broth , mustard , chili powder and pepper"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-242513', '24 Hour Chicken Casserole', 1460, ARRAY['cooked rice', 'chicken'], '["mix all ingredients except crackers and butter", "put mixture in greased baking dish and let sit in refrigerator for 24 hours", "remove from refrigerator and let sit at room temperature for 30 minutes", "meanwhile , mix crushed crackers and melted butter", "spoon cracker mixture over chicken mixture"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-281328', '2Bleu S Bacon Cheeseburger Roll Up', 45, ARRAY['beef', 'bacon'], '["preheat oven to 400f", "cook ground beef , onions , and italian seasoning in large skillet on medium-high heat until ground beef is evenly browned", "drain and return meat mixture to skillet", "add cheese and bacon and cook until the cheese is mostly melted , stirring frequently", "cool 10 minutes"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-460167', '2Bleu S Pepperoni Pizza Burgers', 25, ARRAY['beef', 'sausage'], '["to a food processor , add the sliced pepperoni", "mix until most of the pepperoni is ground up , pulsing as you go", "add the ground beef and sausage", "form meat into 4 patties", "to a large skillet over medium / med-high heat , melt the butter and olive oil until butter is melted"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-388488', '3 Alarm Chili', 65, ARRAY['turkey', 'chicken'], '["brown the meat in a large skillet", "once cooked through , add the onions , tomatoes , garlic , and a tablespoon of canola oil", "saute until the onions are slightly browned or colored by the tomatoes", "add the seasonings", "cook two minutes ensuring that everything is coated by the seasonings"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-187438', '3 Bean Baked Beans', 80, ARRAY['pork', 'bacon'], '["in a large bowl combine cooked bacon , hamburger , onion , kidney beans , pork and beans and butter beans", "mix together brown and white sugar , ketchup , molasses and dry mustard", "combine this mixture with the beans", "bake uncovered for 1 hour at 350 degrees fahrenheit"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-114204', '3 Cheese Chicken Enchiladas', 40, ARRAY['sour cream', 'chicken'], '["heat oven to 350 degrees", "in a large bowl , mix together the cream cheese and sour cream until it is smooth", "stir in cumin , salt and pepper", "add the chicken , 1 cup monterey jack cheese and the cheddar cheese", "dip the tortillas in the enchilada sauce to lightly coat"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-100450', '3 Meat Breakfast Pizza', 25, ARRAY['sausage', 'bacon'], '["preheat oven to 400f", "in saucepan add water and milk", "whisk in gravy mix , and bring to a boil", "simmer 2-3 minutes , stirring constantly til thick", "cool slightly"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-335058', '3 Day Barbecued Marinated Beef Brisket', 275, ARRAY['beef', 'chicken'], '["first day: combine liquid smoke , worcestershire sauce , beef concentrate , garlic and 1 cup barbecue sauce", "marinate brisket in this mixture in the refrigerator overnight , tightly covered", "second day: bake , uncovered , in a 300 degree oven for 4 hours", "cool , wrap tightly in foil , and refrigerate overnight", "third day: remove meat , discard foil , slice brisket across grain and pour remaining barbecue sauce over meat"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-531161', '3 Ingredient Carnitas', 190, ARRAY['pork', 'sour cream'], '["preheat oven to 350 degrees f", "add pork , water or chicken stock , and 1 tablespoon salt to a large dutch oven with a tight fitting lid", "liquid should just cover meat", "add additional as necessary", "place over medium-high heat and bring to a boil"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
INSERT INTO recipes (recipe_id, title, prep_time_minutes, matched_ingredients, instructions) VALUES ('rec-111880', '3 Layer Mexican Party Dip', 30, ARRAY['sour cream', 'guacamole', 'olives'], '["spread the beans over the bottom of a 10\" round glass baking dish", "cover in guacamole", "in a separate bowl , combine the sour cream and spices", "spread over the guacamole with spatula", "sprinkle the top with the cheese , tomatoes , olives and scallions"]'::jsonb) ON CONFLICT (recipe_id) DO NOTHING;
